const Navbar = ({ onOpenGallery }: { onOpenGallery: () => void }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);
  return (
    <motion.nav
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled || isMobileMenuOpen ? 'bg-cream/95 backdrop-blur-md shadow-sm py-3' : 'bg-transparent py-5'
      }`}
    >
      <div className="max-w-7xl mx-auto px-5 flex justify-between items-center">
        <div className="text-2xl font-display font-black tracking-tighter text-ink flex items-center gap-2">
          <div className="w-8 h-8 bg-saffron rounded-full flex items-center justify-center text-white">
            <ChefHat size={18} />
          </div>
          JULA<span className="text-saffron">.</span>
        </div>
        <div className="hidden md:flex items-center gap-8 font-medium text-sm uppercase tracking-wider">
          <button onClick={() => setIsMenuOpen(true)} className="hover:text-saffron transition-colors">Menu</button>
          <a href="#why-us" className="hover:text-emerald transition-colors">Why Us</a>
          <button onClick={onOpenGallery} className="hover:text-cobalt transition-colors">Our Kitchen</button>
          <button className="bg-ink text-white px-6 py-3 rounded-full hover:bg-saffron transition-colors hover-expand">
            Book Tasting
          </button>
        </div>
        <button className="md:hidden text-ink p-2" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X size={26} /> : <Menu size={26} />}
        </button>
      </div>
      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="md:hidden overflow-hidden bg-cream/97 backdrop-blur-md border-t border-ink/5 mt-3"
          >
            <div className="flex flex-col items-center py-6 gap-5 font-medium text-sm uppercase tracking-wider">
              <button onClick={() => { setIsMobileMenuOpen(false); setIsMenuOpen(true); }} className="hover:text-saffron transition-colors">Menu</button>
              <a href="#why-us" onClick={() => setIsMobileMenuOpen(false)} className="hover:text-emerald transition-colors">Why Us</a>
              <button onClick={() => { setIsMobileMenuOpen(false); onOpenGallery(); }} className="hover:text-cobalt transition-colors">Our Kitchen</button>
              <button className="bg-ink text-white px-8 py-3 rounded-full hover:bg-saffron transition-colors mt-2">
                Book Tasting
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
};

const FloatingElement = ({ children, delay = 0, yOffset = 20, duration = 4, className = "" }: any) => (
  <motion.div
    animate={{ y: [0, -yOffset, 0], rotate: [0, 5, -5, 0] }}
    transition={{ duration, repeat: Infinity, ease: "easeInOut", delay }}
    className={`absolute pointer-events-none ${className}`}
  >
    {children}
  </motion.div>
);

