const MenuSection = () => {
  const [activeCategory, setActiveCategory] = useState('Non-Vegetarian');
  const [activeProtein, setActiveProtein] = useState('All');
  const filteredItems = MENU_ITEMS.filter(item =>
    (activeCategory === 'All' || item.category === activeCategory) &&
    (activeProtein === 'All' || item.protein === activeProtein)
  );
  return (
    <section id="menu" className="py-20 md:py-32 bg-ink text-cream relative overflow-hidden">
      <div className="max-w-7xl mx-auto px-5 relative z-10">
        <div className="flex flex-col md:flex-row justify-between items-end mb-10 md:mb-16 gap-6">
          <div>
            <h2 className="text-4xl md:text-7xl font-display font-black uppercase tracking-tighter mb-3">
              Explosive <br/><span className="text-coral">Flavors.</span>
            </h2>
            <p className="text-base text-cream/70 max-w-md">Curated menus designed to impress executives and satisfy thousands.</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {MENU_CATEGORIES.map(cat => (
              <button key={cat} onClick={() => setActiveCategory(cat)}
                className={`px-3 py-1.5 rounded-full text-xs font-bold uppercase tracking-wider transition-all ${
                  activeCategory === cat ? 'bg-coral text-white' : 'bg-white/10 text-white hover:bg-white/20'
                }`}>
                {cat}
              </button>
            ))}
          </div>
        </div>
        <div className="mb-8 flex flex-wrap gap-2 items-center">
          <span className="text-xs font-bold uppercase tracking-widest text-cream/50 mr-1">Protein:</span>
          {PROTEINS.map(protein => (
            <button key={protein} onClick={() => setActiveProtein(protein)}
              className={`px-3 py-1 rounded-md text-xs font-bold uppercase transition-all ${
                activeProtein === protein ? 'bg-white text-ink' : 'border border-white/20 text-white/70 hover:border-white/50'
              }`}>
              {protein}
            </button>
          ))}
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5 md:gap-8">
          <AnimatePresence mode="popLayout">
            {filteredItems.map((item, i) => (
              <motion.div layout initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.8 }} transition={{ duration: 0.4, delay: i * 0.1 }}
                key={item.id} className="group relative h-[280px] md:h-[400px] rounded-2xl md:rounded-3xl overflow-hidden cursor-pointer">
                <img src={item.image} alt={item.name} className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                <div className={`absolute inset-0 ${item.color} mix-blend-multiply opacity-0 group-hover:opacity-80 transition-opacity duration-500`}></div>
                <div className="absolute inset-0 bg-gradient-to-t from-ink/90 via-ink/20 to-transparent opacity-80"></div>
                <div className="absolute inset-0 p-6 md:p-8 flex flex-col justify-end">
                  <span className="text-xs font-bold uppercase tracking-widest text-white/70 mb-1 block">{item.category} • {item.protein}</span>
                  <h3 className="text-xl md:text-3xl font-display font-black leading-tight text-white mb-3">{item.name}</h3>
                  <div className="w-10 h-1 bg-white rounded-full transform origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-500 delay-100"></div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      </div>
    </section>
  );
};

