const KitchenGallery = ({ isOpen, onClose }: { isOpen: boolean, onClose: () => void }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const images = [
    { img: IMG_KITCHEN2, caption: "From Farm to Your Plate — Every Step Monitored" },
    { img: IMG_KITCHEN3, caption: "The Jula Team — Culinary Experts in Orange" },
  ];
  const next = () => setCurrentIndex((prev) => (prev + 1) % images.length);
  const prev = () => setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);
  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
          className="fixed inset-0 z-[100] bg-ink flex items-center justify-center">
          <button onClick={onClose} className="absolute top-5 right-5 text-white hover:text-saffron z-50 transition-colors">
            <X size={36} />
          </button>
          <div className="absolute inset-0">
            <AnimatePresence mode="wait">
              <motion.img key={currentIndex} src={images[currentIndex].img}
                initial={{ opacity: 0, scale: 1.08 }} animate={{ opacity: 0.65, scale: 1 }} exit={{ opacity: 0 }}
                transition={{ duration: 0.8 }}
                className="w-full h-full object-cover object-center md:object-center"
                style={{ objectPosition: currentIndex === 1 ? 'center top' : 'center center' }}
              />
            </AnimatePresence>
          </div>
          <div className="relative z-10 w-full max-w-7xl mx-auto px-5 flex items-center justify-between">
            <button onClick={prev} className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center text-white hover:bg-white hover:text-ink transition-all">
              <ChevronLeft size={24} />
            </button>
            <div className="text-center px-4">
              <motion.h2 key={currentIndex} initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }}
                className="text-2xl md:text-6xl font-display font-black text-white uppercase tracking-widest mb-3">
                Our Kitchen
              </motion.h2>
              <motion.p key={`p-${currentIndex}`} initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: 0.1 }}
                className="text-sm md:text-xl text-white/80 font-medium bg-ink/50 px-4 py-2 rounded-full inline-block backdrop-blur-sm">
                {images[currentIndex].caption}
              </motion.p>
            </div>
            <button onClick={next} className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center text-white hover:bg-white hover:text-ink transition-all">
              <ChevronRight size={24} />
            </button>
          </div>
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex gap-3">
            {images.map((_, i) => (
              <div key={i} className={`h-2 rounded-full transition-all duration-500 ${i === currentIndex ? 'w-10 bg-saffron' : 'w-2 bg-white/30'}`} />
            ))}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

